407	<script>
408	(function () {
409	  // The minimal animation stylesheet each asset depends on. Embedded inside the
410	  // copied <svg> so the asset stays self-animating when dropped into any project.
411	  var ANIM_CSS = [
412	    '@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}',
413	    '@keyframes blink{0%,92%,100%{transform:scaleY(1)}96%{transform:scaleY(.1)}}',
414	    '@keyframes sway{0%,100%{transform:rotate(-4deg)}50%{transform:rotate(4deg)}}',
415	    '@keyframes pop{0%{transform:scale(0);opacity:0}60%{transform:scale(1.15);opacity:1}100%{transform:scale(1)}}',
416	    '@keyframes draw{to{stroke-dashoffset:0}}',
417	    '@keyframes confetti{0%{transform:translateY(0) rotate(0);opacity:1}100%{transform:translateY(-46px) rotate(220deg);opacity:0}}',
418	    '@keyframes spin{to{transform:rotate(360deg)}}',
419	    '@keyframes pulse{0%,100%{transform:scale(1);opacity:.9}50%{transform:scale(1.12);opacity:.5}}',
420	    '@keyframes wiggle{0%,100%{transform:rotate(0)}25%{transform:rotate(8deg)}75%{transform:rotate(-8deg)}}',
421	    '@keyframes orbit{to{transform:rotate(-360deg)}}',
422	    '@keyframes rise{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}',
423	    '@keyframes twinkle{0%,100%{opacity:.2;transform:scale(.6)}50%{opacity:1;transform:scale(1)}}',
424	    '@keyframes heartbeat{0%,100%{transform:scale(1)}15%{transform:scale(1.13)}30%{transform:scale(1)}45%{transform:scale(1.08)}}',
425	    '.a-float{animation:float 4s ease-in-out infinite;transform-origin:center}',
426	    '.a-blink{animation:blink 5s ease-in-out infinite;transform-origin:center}',
427	    '.a-sway{animation:sway 4.5s ease-in-out infinite;transform-origin:50% 90%}',
428	    '.a-pop{animation:pop .7s cubic-bezier(.2,1.3,.4,1) both}',
429	    '.a-spin{animation:spin 1.4s linear infinite;transform-origin:center}',
430	    '.a-pulse{animation:pulse 2.6s ease-in-out infinite;transform-origin:center}',
431	    '.a-wiggle{animation:wiggle 3.5s ease-in-out infinite;transform-origin:50% 80%}',
432	    '.a-orbit{animation:orbit 6s linear infinite;transform-origin:center}',
433	    '.a-rise{animation:rise 3s ease-in-out infinite;transform-origin:center}',
434	    '.a-twinkle{animation:twinkle 2s ease-in-out infinite;transform-origin:center}',
435	    '.a-heartbeat{animation:heartbeat 2.4s ease-in-out infinite;transform-origin:center}',
436	    '.draw{stroke-dasharray:90;stroke-dashoffset:90;animation:draw 1s ease-out .25s forwards}',
437	    '.conf{animation:confetti 1.3s ease-out infinite}',
438	    '.conf:nth-child(odd){animation-duration:1.6s}',
439	    '@media (prefers-reduced-motion:reduce){.a-float,.a-blink,.a-sway,.a-pop,.a-spin,.a-pulse,.a-wiggle,.a-orbit,.a-rise,.a-twinkle,.a-heartbeat,.conf{animation:none}.draw{stroke-dashoffset:0}}'
440	  ].join('');
441	
442	  // Build standalone, self-animating SVG markup for one card's stage <svg>.
443	  function buildSvg(svg) {
444	    var clone = svg.cloneNode(true);
445	    var style = document.createElementNS('http://www.w3.org/2000/svg', 'style');
446	    style.textContent = ANIM_CSS;
447	    clone.insertBefore(style, clone.firstChild);
448	    if (!clone.getAttribute('xmlns')) clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
449	    return clone.outerHTML.replace(/></g, '>\n<');
450	  }
451	
452	  var toast = document.getElementById('toast'), toastTimer;
453	  function showToast(msg) {
454	    toast.textContent = msg;
455	    toast.classList.add('show');
456	    clearTimeout(toastTimer);
457	    toastTimer = setTimeout(function () { toast.classList.remove('show'); }, 1800);
458	  }
459	
460	  var COPY_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>';
461	  var DONE_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 13l4 4L19 7"/></svg>';
462	  var DL_IC   = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12"/><path d="M7 11l5 5 5-5"/><path d="M5 20h14"/></svg>';
463	
464	  // "Nothing here — yet" -> "nothing-here-yet" for a friendly .svg filename
465	  function slugify(name) {
466	    return (name || 'asset').toLowerCase()
467	      .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'asset';
468	  }
469	
470	  // Save a standalone .svg document (self-animating markup + XML prolog) to disk.
471	  function downloadSvg(markup, filename) {
472	    var doc = '<?xml version="1.0" encoding="UTF-8"?>\n' + markup;
473	    var blob = new Blob([doc], { type: 'image/svg+xml' });
474	    var url = URL.createObjectURL(blob);
475	    var a = document.createElement('a');
476	    a.href = url; a.download = filename;
477	    document.body.appendChild(a); a.click(); document.body.removeChild(a);
478	    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
479	  }
480	
481	  function fallbackCopy(text) {
482	    var ta = document.createElement('textarea');
483	    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
484	    document.body.appendChild(ta); ta.select();
485	    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
486	    document.body.removeChild(ta); return ok;
487	  }
488	
489	  document.querySelectorAll('.card').forEach(function (card) {
490	    var svg = card.querySelector('.stage svg');
491	    if (!svg) return;
492	    var name = (card.querySelector('.name') || {}).textContent || 'asset';
493	    var btn = document.createElement('button');
494	    btn.type = 'button';
495	    btn.className = 'copy-btn';
496	    btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
497	    btn.setAttribute('aria-label', 'Copy SVG markup for ' + name);
498	
499	    btn.addEventListener('click', function () {
500	      var markup = buildSvg(svg);
501	      var done = function () {
502	        btn.classList.add('done');
503	        btn.innerHTML = DONE_IC + '<span>Copied!</span>';
504	        showToast('SVG copied — paste it anywhere');
505	        setTimeout(function () {
506	          btn.classList.remove('done');
507	          btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
508	        }, 1800);
509	      };
510	      if (navigator.clipboard && navigator.clipboard.writeText) {
511	        navigator.clipboard.writeText(markup).then(done, function () {
512	          if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
513	        });
514	      } else {
515	        if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
516	      }
517	    });
518	
519	    var dl = document.createElement('button');
520	    dl.type = 'button';
521	    dl.className = 'dl-btn';
522	    dl.innerHTML = DL_IC;
523	    dl.setAttribute('aria-label', 'Download ' + name + ' as an SVG file');
524	    dl.title = 'Download .svg';
525	    dl.addEventListener('click', function () {
526	      downloadSvg(buildSvg(svg), slugify(name) + '.svg');
527	      showToast('Downloaded ' + slugify(name) + '.svg');
528	    });
529	
530	    var actions = document.createElement('div');
531	    actions.className = 'actions';
532	    actions.appendChild(btn);
533	    actions.appendChild(dl);
534	    card.querySelector('.body').appendChild(actions);
535	  });
536	
537	  // ---- Journey-stage filtering ----
538	  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
539	  var chips = Array.prototype.slice.call(document.querySelectorAll('.filterbar .chip'));
540	  var countEl = document.getElementById('fbCount');
541	  var emptyNote = document.getElementById('emptyNote');
542	
543	  function applyFilter(filter) {
544	    var shown = 0;
545	    cards.forEach(function (card) {
546	      var match = filter === 'all' || card.getAttribute('data-cat') === filter;
547	      card.classList.toggle('hide', !match);
548	      if (match) shown++;
549	    });
550	    chips.forEach(function (chip) {
551	      chip.setAttribute('aria-pressed', String(chip.getAttribute('data-filter') === filter));
552	    });
553	    countEl.textContent = shown + (shown === 1 ? ' asset' : ' assets');
554	    emptyNote.style.display = shown === 0 ? 'block' : 'none';
555	  }
556	
557	  chips.forEach(function (chip) {
558	    chip.addEventListener('click', function () { applyFilter(chip.getAttribute('data-filter')); });
559	  });
560	})();
561	</script>
