.motion-toggle {
  margin-left: auto; font: inherit; font-size: 12.5px; font-weight: 700; cursor: pointer;
  color: var(--muted); background: var(--panel); border: 1px solid var(--border); border-radius: 999px;
  padding: 7px 14px; transition: .15s; -webkit-font-smoothing: antialiased;
  display: inline-flex; align-items: center; gap: 7px;
}
.motion-toggle:hover { border-color: var(--accent); color: var(--text); transform: translateY(-1px); }
.motion-toggle svg.ic { width: 14px; height: 14px; overflow: visible; }
.motion-toggle .mt-pause { display: inline; }
.motion-toggle .mt-play  { display: none; }
body.motion-paused .motion-toggle .mt-pause { display: none; }
body.motion-paused .motion-toggle .mt-play  { display: inline; }
body.motion-paused .motion-toggle { border-color: var(--accent); color: var(--accent); }

.fb-count { margin-left: 4px; font-size: 12.5px; color: var(--faint); font-weight: 600; }

